// Generated by `just generate` from `src/plugins/claudetto/slices/setup/domain/hard-stop.ts`. Edit the source and run `just generate`.
// The hard stop of the AI policy: sandbox settings that block each GitHub host for the shell commands of Claude.
// The `sandbox` command of `claudetto-setup` writes them to `.claude/settings.local.json` of a checkout that the user does not own,
// when the policy verdict of that repository is not `allowed` or `conditions`.
// The keys come from the settings reference of Claude Code (https://code.claude.com/docs/en/settings-reference):
// `deniedDomains` blocks a host "even when an `allowedDomains` entry matches it too",
// `allowUnsandboxedCommands: false` makes Claude Code ignore `dangerouslyDisableSandbox`,
// and `failIfUnavailable: true` stops Claude Code at startup when the sandbox cannot start, in place of a run with no sandbox.
// The command keeps a record of what it changed, so that the remove mode takes out only that and puts back each old value.
// This file reads no file and runs no program, so it has no `node:` import.

import type { Repo } from "../../../kernel/repo/remote.ts";
import { isOwn } from "../../../kernel/repo/remote.ts";
import { STOP_HOSTS } from "../../../kernel/repo/stop-hosts.ts";
import { isObject, mergeSettings } from "./merge.ts";
import type { Change, Json } from "./types.ts";

/** The Boolean keys of `sandbox` that the hard stop sets, and their values. */
const SWITCHES: Readonly<Record<string, boolean>> = {
  enabled: true,
  failIfUnavailable: true,
  allowUnsandboxedCommands: false,
};

/** The settings of the hard stop. */
export const HARD_STOP: Json = {
  sandbox: { ...SWITCHES, network: { deniedDomains: [...STOP_HOSTS] } },
};

/** What the command changed: each key of `sandbox` with its old value, when it had one, and each host that it added. */
export type StopRecord = {
  set: { key: string; had?: unknown }[];
  denied: string[];
};

/** Why the command writes the hard stop to a checkout, or why it does not. */
export type StopCase = "no-origin" | "own" | "cleared" | "stop";

/**
 * The case of a checkout: the repository of its `origin`, the owners of the user in lower case, and the stored verdict word.
 * The owner test is the one of the `policy` slice.
 * A checkout with no verdict yet gets the hard stop, because only `allowed` and `conditions` clear a repository.
 */
export const stopCaseOf = (
  repo: Repo | undefined,
  owners: ReadonlySet<string>,
  verdict: string | undefined,
): StopCase => {
  if (repo === undefined) return "no-origin";
  if (isOwn(repo, owners)) return "own";
  if (verdict === "allowed" || verdict === "conditions") return "cleared";
  return "stop";
};

/** The `sandbox` object of `settings`, or `{}`. */
const sandboxOf = (settings: unknown): Json => {
  const box = isObject(settings) ? settings["sandbox"] : undefined;
  return isObject(box) ? box : {};
};

/** The `sandbox.network.deniedDomains` list of `settings`, or `[]`. */
const deniedOf = (settings: unknown): unknown[] => {
  const network = sandboxOf(settings)["network"];
  const list = isObject(network) ? network["deniedDomains"] : undefined;
  return Array.isArray(list) ? list : [];
};

/**
 * The hard stop merged into `current`, the change lines, and the record of the changes.
 * `record` is the record of an earlier run. The new record keeps it and adds only what this run changes.
 */
export const planStop = (
  current: unknown,
  record: StopRecord = { set: [], denied: [] },
): { settings: Json; changes: Change[]; record: StopRecord } => {
  const { settings, changes } = mergeSettings(current, HARD_STOP);
  const box = sandboxOf(current);
  const set = [...record.set];
  for (const [key, value] of Object.entries(SWITCHES)) {
    if (box[key] === value || set.some((s) => s.key === key)) continue;
    set.push(box[key] === undefined ? { key } : { key, had: box[key] });
  }
  const had = deniedOf(current);
  const denied = [
    ...record.denied,
    ...STOP_HOSTS.filter((h) => !had.includes(h) && !record.denied.includes(h)),
  ];
  return { settings, changes, record: { set, denied } };
};

/** `obj` with no key `key` when its value is an empty object or an empty list. */
const pruned = (obj: Json, key: string): Json => {
  const value = obj[key];
  const empty =
    (Array.isArray(value) && value.length === 0) ||
    (isObject(value) && Object.keys(value).length === 0);
  if (!empty) return obj;
  const { [key]: _gone, ...rest } = obj;
  return rest;
};

/**
 * `current` with the changes of `record` taken out, and one change line for each.
 * A key that still has the value of the hard stop gets its old value back, or goes when it had none.
 * A key that the user changed after the run stays as it is.
 * Each host of `record.denied` leaves the deny list, and an empty list or object goes.
 */
export const removeStop = (
  current: unknown,
  record: StopRecord,
): { settings: Json; changes: Change[] } => {
  const changes: Change[] = [];
  let box: Json = { ...sandboxOf(current) };
  for (const { key, ...old } of record.set) {
    if (box[key] !== SWITCHES[key]) continue;
    const where = `sandbox.${key}`;
    const back = "had" in old ? JSON.stringify(old.had) : "(unset)";
    changes.push({ key: where, line: `${where}: ${box[key]} -> ${back}` });
    if ("had" in old) box[key] = old.had;
    else delete box[key];
  }
  const list = deniedOf(current);
  const kept = list.filter((h) => !record.denied.includes(h as string));
  if (kept.length !== list.length) {
    const where = "sandbox.network.deniedDomains";
    changes.push({
      key: where,
      line: `${where}: ${JSON.stringify(list)} -> ${JSON.stringify(kept)}`,
    });
    const network = box["network"] as Json;
    box["network"] = pruned(
      { ...network, deniedDomains: kept },
      "deniedDomains",
    );
    box = pruned(box, "network");
  }
  const out: Json = isObject(current) ? { ...current } : {};
  if (!changes.length) return { settings: out, changes };
  return { settings: pruned({ ...out, sandbox: box }, "sandbox"), changes };
};

/**
 * The entries of `sandbox.excludedCommands` in the settings `files`.
 * Claude Code merges the list across the settings files, and an excluded command runs with no sandbox, so it can reach GitHub.
 */
export const bypassesOf = (files: readonly unknown[]): string[] => [
  ...new Set(
    files.flatMap((file) => {
      const list = sandboxOf(file)["excludedCommands"];
      return Array.isArray(list)
        ? list.filter((c): c is string => typeof c === "string")
        : [];
    }),
  ),
];

/** The record in the parsed record file `data`, or `undefined` when `data` is not a record. */
export const recordOf = (data: unknown): StopRecord | undefined => {
  if (!isObject(data)) return undefined;
  const { set, denied } = data;
  if (!Array.isArray(set) || !Array.isArray(denied)) return undefined;
  const keys = set.filter(
    (s): s is StopRecord["set"][number] =>
      isObject(s) && typeof s["key"] === "string" && s["key"] in SWITCHES,
  );
  const hosts = denied.filter((h): h is string => typeof h === "string");
  return { set: keys, denied: hosts };
};
